// ============================================================
// EXTRAÇÃO E SEPARAÇÃO DE PUBLICAÇÕES DO E-MAIL
// ============================================================

const item = $input.item.json;
const emailId = item.messageId || item.id || item.uid || '';

let raw = item.text || item.textPlain || '';

if (!raw && item.html) {
  raw = item.html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')        
    .replace(/<\/p>/gi, '\n')             
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')               
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"');
}

raw = raw.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

const advogado =
  (raw.match(/Advogado\(a\)\s*[:\-]?\s*([^\n]+)/) || [])[1]?.trim() || '';

const oab =
  (raw.match(/(?:Número da OAB|OAB)\s*[:\-]?\s*([^\n]+)/) || [])[1]?.trim() || '';

const dataProcessamento =
  (raw.match(/Data\s*(?:\n)?processamento\/pesquisa\s*[:\-]?\s*([^\n]+)/) || [])[1]?.trim() ||
  (raw.match(/Data de processamento\s*[:\-]?\s*([^\n]+)/) || [])[1]?.trim() || '';

const assuntoOriginal = item.subject || '';

function parseDateBR(str) {
  if (!str) return null;
  const partes = str.trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!partes) return null;
  return new Date(`${partes[3]}-${partes[2]}-${partes[1]}`);
}

const partes = raw.split(/Publicação:\s*(\d+)\./);
const publicacoes = [];

for (let i = 1; i < partes.length; i += 2) {
  const numeroPublicacao = partes[i];
  const block = partes[i + 1] || '';

  const marcadores = ['- ADV:', '||| ADV:', '|||']
    .map((m) => block.indexOf(m))
    .filter((idx) => idx !== -1);
  const corteIdx = marcadores.length ? Math.min(...marcadores) : block.length;
  const corpo = block.slice(0, corteIdx);

  const get = (regex) => (block.match(regex) || [])[1]?.trim() || '';

  const dataDisponibilizacao = get(/Data de Disponibiliza[çc][ãa]o\s*[:\-]?\s*([^\n]+)/i);
  const dataPublicacao        = get(/Data de Publica[çc][ãa]o\s*[:\-]?\s*([^\n]+)/i);
  const jornal                = get(/Jornal\s*[:\-]?\s*([^\n]+)/i);
  const vara                  = get(/Vara\s*[:\-]?\s*([^\n]+)/i);
  const processo              = get(/PROCESSO\s*[:\-]?\s*([\d.\-\/]+)/i);
  const documentoId           = get(/Identificador do documento\s*[:\-]?\s*([^\n.]+)/i);

  const tipo =
    get(/Tipo\s*[:\-]?\s*([^\n]+)/i) ||
    get(/Esp[eé]cie\s*[:\-]?\s*([^\n]+)/i) ||
    get(/Natureza\s*[:\-]?\s*([^\n]+)/i) ||
    '';

  const link =
    (block.match(/Acesso ao documento\s*[:\-]?\s*(https?:\/\/\S+)/i) || [])[1]?.trim() || '';

  const prazoMatch = block.match(/(?:prazo|preclusivo|impreter[ií]vel)?[\s\S]{0,35}?(\d+)\s*(?:\([a-zçãõ\s]+\)\s*)?dias?/i) || block.match(/Prazo\s*[:\-]?\s*(\d+)/i);
  const prazoDias  = prazoMatch ? parseInt(prazoMatch[1], 10) : null;

  let dataLimite = '';
  let dataLimiteISO = '';
  const baseDate = parseDateBR(dataPublicacao);
  if (baseDate && prazoDias !== null) {
    baseDate.setDate(baseDate.getDate() + prazoDias);
    const dd = String(baseDate.getDate()).padStart(2, '0');
    const mm = String(baseDate.getMonth() + 1).padStart(2, '0');
    const aaaa = baseDate.getFullYear();
    dataLimite = `${dd}/${mm}/${aaaa}`;
    dataLimiteISO = `${aaaa}-${mm}-${dd}`;
  }

  const resumo = corpo.replace(/\s+/g, ' ').trim().slice(0, 3000);

  publicacoes.push({
    emailId,
    numeroPublicacao,
    processo,
    tipo,
    documentoId,
    vara,
    jornal,
    dataDisponibilizacao,
    dataPublicacao,
    dataLimite,
    dataLimiteISO,
    prazoDias,
    resumo,
    link,
  });
}

if (publicacoes.length === 0) {
  return [{
    json: {
      erro: 'Nenhuma publicação encontrada no e-mail.',
      assuntoOriginal,
      advogado,
      oab,
      dataProcessamento,
      rawPreview: raw.slice(0, 300),
    },
  }];
}

return publicacoes.map((p) => ({
  json: {
    advogado,
    oab,
    dataProcessamento,
    assuntoOriginal,
    ...p,
  },
}));

// ============================================================
// MARCADOR VIRTUAL DO N8N (ANTI-DUPLICIDADE ROBUSTO)
// ============================================================
// Evita disparos repetidos gravando os números de processos já tratados.

let staticData;
try {
  staticData = $getWorkflowStaticData('node');
} catch(e) {
  staticData = $getWorkflowStaticData('global');
}

const processados = Array.isArray(staticData.processados) ? staticData.processados : [];
let novosProcessados = [...processados];
const novasPublicacoes = [];

for (const item of $input.all()) {
  const p = item.json;
  if (p.erro) continue;

  // Chave única padronizada pelo número limpo do processo (somente dígitos)
  const procLimpo = (p.processo || '').replace(/\D/g, '');
  const chaveUnica = procLimpo ? `PROC_${procLimpo}` : (p.emailId ? `EMAIL_${p.emailId}` : null);

  if (!chaveUnica) {
    novasPublicacoes.push(item);
    continue;
  }

  // Se já foi processada anteriormente pelo n8n, DESCARTA!
  if (novosProcessados.includes(chaveUnica)) {
    continue;
  }

  novosProcessados.push(chaveUnica);
  novasPublicacoes.push(item);
}

// ATRIBUIÇÃO DIRETA: No n8n, reatribuir a propriedade é obrigatório para persistir no banco SQLite/Postgres
staticData.processados = novosProcessados.slice(-2000);

return novasPublicacoes;

