// Busca dados correspondentes da publicação
const dadosOriginais = $('Marcador n8n (Anti-Duplicidade)').item.json || $('Code in JavaScript').item.json;
const infoExtraida = $input.item.json?.output || $input.item.json || {};

// Obtém a data limite em formato seguro AAAA-MM-DD
let dataISO = dadosOriginais.dataLimiteISO;

if (!dataISO && dadosOriginais.dataLimite) {
  const p = dadosOriginais.dataLimite.split('/');
  if (p.length === 3) dataISO = `${p[2]}-${p[1]}-${p[0]}`;
}

if (!dataISO && infoExtraida.prazo_data && infoExtraida.prazo_data !== 'Sem prazo') {
  const p = String(infoExtraida.prazo_data).split('/');
  if (p.length === 3) dataISO = `${p[2]}-${p[1]}-${p[0]}`;
}

if (!dataISO) {
  return [{ json: { ...$json, dataAlerta: null } }];
}

let dataAlerta = new Date(`${dataISO}T09:00:00`);

if (isNaN(dataAlerta.getTime())) {
  return [{ json: { ...$json, dataAlerta: null } }];
}

let diasSubtraidos = 0;

// Subtrai exatamente 3 dias ÚTEIS para gerar o alerta
while (diasSubtraidos < 3) {
  dataAlerta.setDate(dataAlerta.getDate() - 1);
  let diaSemana = dataAlerta.getDay();

  if (diaSemana !== 0 && diaSemana !== 6) {
    diasSubtraidos++;
  }
}

return [{ json: { ...$json, dataAlerta: dataAlerta.toISOString() } }];

